class NotificationHub:
    """Bounded, process-local cursor used by authenticated SSE handlers."""

    def __init__(self, max_items: int = MAX_LOCAL_NOTIFICATIONS) -> None:
        self._items: deque[Notification] = deque(maxlen=max(32, int(max_items)))
        self._sequence = 0
        self._subscriber_sequence = 0
        self._subscribers: dict[int, Callable[[Notification], None]] = {}
        self._condition = threading.Condition()

    @property
    def sequence(self) -> int:
        with self._condition:
            return self._sequence

    def publish(self, subject: str, payload: dict[str, Any]) -> Notification:
        with self._condition:
            self._sequence += 1
            notification = Notification(
                sequence=self._sequence,
                subject=str(subject or ""),
                payload=dict(payload),
                received_at=time.time(),
            )
            self._items.append(notification)
            subscribers = list(self._subscribers.values())
            self._condition.notify_all()
        for subscriber in subscribers:
            try:
                subscriber(notification)
            except Exception:
                continue
        return notification

    def subscribe(
        self,
        callback: Callable[[Notification], None],
    ) -> Callable[[], None]:
        with self._condition:
            self._subscriber_sequence += 1
            subscription_id = self._subscriber_sequence
            self._subscribers[subscription_id] = callback

        def unsubscribe() -> None:
            with self._condition:
                self._subscribers.pop(subscription_id, None)

        return unsubscribe

    def cursor_has_gap(self, after_sequence: int) -> bool:
        cursor = max(0, int(after_sequence))
        with self._condition:
            return bool(
                self._items
                and cursor < self._items[0].sequence - 1
            )

    def wait(
        self,
        after_sequence: int,
        *,
        predicate: Callable[[Notification], bool] | None = None,
        timeout: float = 15.0,
    ) -> tuple[list[Notification], int]:
        cursor = max(0, int(after_sequence))
        deadline = time.monotonic() + max(0.0, float(timeout))
        with self._condition:
            while True:
                matches = [
                    item
                    for item in self._items
                    if item.sequence > cursor
                    and (predicate is None or predicate(item))
                ]
                if matches:
                    return matches, self._sequence
                remaining = deadline - time.monotonic()
                if remaining <= 0:

                self._condition.wait(remaining)


class NatsNotificationPublisher:
    """Best-effort NATS publisher with a bounded, non-blocking caller path."""

    def __init__(self, *, component: str = "publisher", queue_size: int = 2048) -> None:
        self.component = str(component or "publisher")
        self._queue: queue.Queue[tuple[str, bytes]] = queue.Queue(
            maxsize=max(32, int(queue_size))
        )
        self._thread: threading.Thread | None = None
        self._stop = threading.Event()
        self._lock = threading.Lock()
        self._published = 0
        self._dropped = 0
        self._last_error = ""
        self._connected = False

    def start(self) -> None:
        if not nats_enabled():
            return
        with self._lock:
            if self._thread is not None and self._thread.is_alive():
                return
            self._stop.clear()
            self._thread = threading.Thread(
                target=self._run,
                name=f"portal-nats-{self.component}",
                daemon=True,
            )
            self._thread.start()

    def close(self, timeout: float = 2.0) -> None:
        self._stop.set()
        thread = self._thread
        if thread is not None:
            thread.join(timeout=max(0.0, float(timeout)))
        with self._lock:
            if self._thread is thread and (thread is None or not thread.is_alive()):
                self._thread = None
            self._connected = False

    def publish(self, subject: str, payload: dict[str, Any] | None = None) -> bool:
        body = json.dumps(
            payload or {"kind": "changed"},
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8")
        if len(body) > MAX_NOTIFICATION_BYTES:
            raise ValueError("notification payload exceeds 900 KiB")
        self.start()
        if not nats_enabled():
            return False
        try:
            self._queue.put_nowait((str(subject or ""), body))
            return True
        except queue.Full:
            with self._lock:
                self._dropped += 1
            return False

    def health(self) -> dict[str, Any]:
        with self._lock:
            return {
                "enabled": nats_enabled(),
                "url": nats_url(),
                "connected": self._connected,
                "queued": self._queue.qsize(),
                "published": self._published,
                "dropped": self._dropped,
                "last_error": self._last_error,
            }

    def _run(self) -> None:
        asyncio.run(self._run_async())

    async def _run_async(self) -> None:
        client = None
        while not self._stop.is_set():
            if client is None or not client.is_connected:
                try:
                    from .nats_client import connect_notifications

                    client = await connect_notifications(
                        servers=[nats_url()],
                        name=nats_client_name(self.component),
                        connect_timeout=1,
                        allow_reconnect=True,
                        max_reconnect_attempts=-1,
                        reconnect_time_wait=1,
                    )
                    with self._lock:
                        self._connected = True
                        self._last_error = ""
                except Exception as exc:
                    with self._lock:
                        self._connected = False
                        self._last_error = f"{exc.__class__.__name__}: {exc}"[:500]
                    await asyncio.sleep(1)
                    continue
            try:
                subject, body = self._queue.get_nowait()
            except queue.Empty:
                await asyncio.sleep(0.1)
                continue
            try:
                await client.publish(subject, body)
                await client.flush(timeout=1)
                with self._lock:
                    self._published += 1
                    self._last_error = ""
            except Exception as exc:
                with self._lock:
                    self._connected = False
                    self._last_error = f"{exc.__class__.__name__}: {exc}"[:500]
                try:
                    self._queue.put_nowait((subject, body))
                except queue.Full:
                    with self._lock:
                        self._dropped += 1
                try:
                    await client.close()
                except Exception:
                    pass
                client = None
        if client is not None:
            try:
                await client.drain()
            except Exception:
                try:
                    await client.close()
                except Exception:
                    pass


class NatsNotificationListener:
    def __init__(self, hub: NotificationHub, *, component: str = "portal-gateway") -> None:
        self.hub = hub
        self.component = component
        self._thread: threading.Thread | None = None

async def wait(self, timeout: float) -> AsyncNotificationBatch | None:
    try:
        first = await asyncio.wait_for(
            self._queue.get(),
            timeout=max(0.0, float(timeout)),
        )
    except asyncio.TimeoutError:
        return None
    if first is _CLOSED:
        return AsyncNotificationBatch(closed=True)
    if first is _SNAPSHOT_REQUIRED:
        self._snapshot_pending = False
        return AsyncNotificationBatch(snapshot_required=True)

    notifications = [first]
    while True:
        try:
            item = self._queue.get_nowait()
        except asyncio.QueueEmpty:
            break
        if item is _CLOSED:
            self._closed = True
            break
        if item is _SNAPSHOT_REQUIRED:
            self._snapshot_pending = False
            return AsyncNotificationBatch(snapshot_required=True)
        notifications.append(item)
    return AsyncNotificationBatch(notifications=tuple(notifications))

def close(self) -> None:
    if self._closed:
        return
    self._closed = True
    self._fanout._unsubscribe(self._subscription_id)

def _offer(self, notification: Notification) -> None:
    if self._closed or self._snapshot_pending:
        return
    try:
        if not self._predicate(notification):
            return
    except Exception:
        return
    try:
        self._queue.put_nowait(notification)
    except asyncio.QueueFull:
        self._require_snapshot()

def _require_snapshot(self) -> None:
    if self._closed or self._snapshot_pending:
        return
    while True:
        try:
            self._queue.get_nowait()
        except asyncio.QueueEmpty:
            break
    self._snapshot_pending = True
    self._queue.put_nowait(_SNAPSHOT_REQUIRED)

def _close_from_fanout(self) -> None:
    if self._closed:
        return
    self._closed = True
    while True:
        try:
            self._queue.get_nowait()
        except asyncio.QueueEmpty:
            break
    self._queue.put_nowait(_CLOSED)

def start(self) -> None:
    loop = asyncio.get_running_loop()
    with self._lock:
        if not self._closed:
            raise RuntimeError("async notification fanout is already started")
        self._loop = loop
        self._closed = False
        self._pending.clear()
        self._pending_overflow = False
        self._drain_scheduled = False
    self._unsubscribe_hub = self._hub.subscribe(self._accept_from_hub)

def subscribe(
    self,
    predicate: Callable[[Notification], bool] | None = None,
) -> AsyncNotificationSubscription:
    if self._closed or self._loop is None:
        raise RuntimeError("async notification fanout is not running")
    if asyncio.get_running_loop() is not self._loop:
        raise RuntimeError("async notification subscription uses another event loop")
    self._subscriber_sequence += 1
    subscription = AsyncNotificationSubscription(
        self,
        self._subscriber_sequence,
        predicate or (lambda _notification: True),
        self._subscriber_queue_size,
    )
    self._subscribers[self._subscriber_sequence] = subscription
    return subscription

def close(self) -> None:
    with self._lock:
        if self._closed:
            return
        self._closed = True
        unsubscribe_hub = self._unsubscribe_hub
        self._unsubscribe_hub = None
        self._pending.clear()
        self._pending_overflow = False
        self._drain_scheduled = False
    if unsubscribe_hub is not None:
        unsubscribe_hub()
    subscribers = tuple(self._subscribers.values())
    self._subscribers.clear()
    for subscription in subscribers:
        subscription._close_from_fanout()

def _unsubscribe(self, subscription_id: int) -> None:
    self._subscribers.pop(subscription_id, None)

def _accept_from_hub(self, notification: Notification) -> None:
    with self._lock:
        if self._closed or self._loop is None:
            return
        if len(self._pending) >= self._pending_limit:
            self._pending.clear()
            self._pending_overflow = True
        elif not self._pending_overflow:
            self._pending.append(notification)
        if self._drain_scheduled:
            return
        self._drain_scheduled = True
        loop = self._loop
    try:
        loop.call_soon_threadsafe(self._drain_pending)
    except RuntimeError:
        with self._lock:
            self._drain_scheduled = False

def _drain_pending(self) -> None:
    with self._lock:
        if self._closed:
            self._drain_scheduled = False
            return
        pending = tuple(self._pending)
        overflow = self._pending_overflow
        self._pending.clear()
        self._pending_overflow = False
        self._drain_scheduled = False
    subscribers = tuple(self._subscribers.values())
    if overflow:
        for subscription in subscribers:
            subscription._require_snapshot()
        return
    for notification in pending:
        for subscription in subscribers:
            subscription._offer(notification)

def _run(self) -> None:
    try:
        libc = ctypes.CDLL(None, use_errno=True)
        init = libc.inotify_init1
        init.argtypes = [ctypes.c_int]
        init.restype = ctypes.c_int
        add_watch = libc.inotify_add_watch
        add_watch.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_uint32]
        add_watch.restype = ctypes.c_int
        fd = int(init(os.O_NONBLOCK | os.O_CLOEXEC))
        if fd < 0:
            error_number = ctypes.get_errno()
            raise OSError(error_number, os.strerror(error_number))
        self._fd = fd
        with self._lock:
            self._add_watch = add_watch
            directories = tuple(
                sorted(self._configured_directories, key=str)
            )
        for directory in directories:
            try:
                if self.recursive:
                    self._add_tree(directory, add_watch)
                else:
                    self._add_directory(directory, add_watch)
            except OSError as exc:
                self._set_error(exc)
        with self._lock:
            self._ready = True

        while not self._stopped.is_set():
            try:
                readable, _writable, _errors = select.select([fd], [], [], 1.0)
            except (OSError, ValueError):
                if self._stopped.is_set():
                    break
                raise
            if not readable:
                continue
            try:
                payload = os.read(fd, 256 * 1024)
            except BlockingIOError:
                continue
            offset = 0
            while offset + self._EVENT.size <= len(payload):
                watch, mask, _cookie, name_length = self._EVENT.unpack_from(
                    payload,
                    offset,
                )
                offset += self._EVENT.size
                raw_name = payload[offset : offset + name_length]
                offset += name_length
                if mask & self._IN_Q_OVERFLOW:
                    self.on_overflow()
                    continue
                with self._lock:
                    directory = self._paths_by_watch.get(watch)
                if directory is None:
                    continue
                name = (
                    os.fsdecode(raw_name.split(b"\0", 1)[0])
                    if raw_name
                    else ""
                )
                path = (
                    (directory / name).resolve(strict=False)
                    if name
                    else directory
                )
                if mask & self._IN_IGNORED:
                    with self._lock:
                        removed = self._paths_by_watch.pop(watch, None)
                        if removed is not None:
                            self._watch_by_path.pop(removed, None)
                    continue
                if mask & self._IN_ISDIR and mask & (
                    self._IN_CREATE | self._IN_MOVED_TO
                ):
                    if self.track_new_directories:
                        self._add_tree(path, add_watch)
                with self._lock:
                    self._last_event_at = _now_iso()
                self.on_change(str(path))
    except Exception as exc:
        if not self._stopped.is_set():
            self._set_error(exc)
    finally:
        with self._lock:
            self._ready = False
            self._add_watch = None
        fd = self._fd
        self._fd = -1
        if fd >= 0:
            try:
                os.close(fd)
            except OSError:
                pass

    resident_ids = {
        resident_id.strip()
        for value in request.query_params.getlist("resident_ids")
        for resident_id in value.split(",")
        if resident_id.strip()
    }

    def accepts(notification) -> bool:
        if notification.subject == "portal.gateway.reconnected":
            return True
        domain, target_id = portal._notification_target(notification.subject)
        if domain not in domains:
            return False
        if domain != "resident" or not notification.subject.endswith(".conversation"):
            return True
        if target_id in resident_ids:
            return True
        event = notification.payload.get("event")
        return (
            notification.payload.get("kind") == "conversation_event"
            and isinstance(event, dict)
            and event.get("event_type") == "resident.state.changed"
        )

    return accepts


async def portal_events(request: Request):
    actor = portal._get_session_username(
        SimpleNamespace(headers=_request_headers(request))
    ) or ""
    if not actor:
        return RedirectResponse("/login", status_code=302)
    domains = _requested_domains(request)
    ensure_notification_listener()
    ensure_knowledge_archive_projection_watcher()
    fanout = getattr(request.app.state, "notification_fanout", None)
    payload_executor = getattr(request.app.state, "sse_payload_executor", None)
    realtime_lifecycle = getattr(
        request.app.state, "realtime_lifecycle", None
    )
    if (
        not isinstance(realtime_lifecycle, RealtimeConnectionLifecycle)
        or not realtime_lifecycle.accepting
        or not isinstance(fanout, AsyncNotificationFanout)
        or payload_executor is None
    ):
        return _json_error(503, "Portal realtime notifications are unavailable")

    async def events() -> AsyncIterator[bytes]:
        connection_id = realtime_lifecycle.open_connection()
        if connection_id is None:
            return
        subscription = fanout.subscribe(_event_subscription_predicate(request, domains))
        drain_wait = asyncio.create_task(realtime_lifecycle.drain_event.wait())
        try:
            yield b"retry: 1500\n\n"
            yield _sse("portal-ready", {"snapshot_required": True})
            while True:
                batch = await subscription.wait(SSE_HEARTBEAT_SECONDS)
                if batch is None:
                    yield _sse("heartbeat", {"at": portal.time.time()})
                    continue
                if batch.closed:
                    return
                if batch.snapshot_required:
                    yield _sse(
                        "portal-change",
                        {
                            "domains": [],
                            "changed": {},
                            "snapshot_required": True,
                        },
                    )
                    continue
                loop = asyncio.get_running_loop()
                payload_future = loop.run_in_executor(
                    payload_executor,
                    partial(
                        portal._portal_change_payload,
                        actor,
                        list(batch.notifications),
                        domains,
                    ),
                )
                try:
                    done, _pending = await asyncio.wait(
                        {payload_future, drain_wait},
                        timeout=SSE_PAYLOAD_TIMEOUT_SECONDS,
                        return_when=asyncio.FIRST_COMPLETED,
                    )
                    if drain_wait in done or realtime_lifecycle.drain_event.is_set():
                        payload_future.cancel()
                        return
                    if payload_future not in done:
                        payload_future.cancel()
                        yield _sse(
                            "portal-change",
                            {
                                "domains": [],
                                "changed": {},
                                "snapshot_required": True,
                            },
                        )
                        continue
                except asyncio.CancelledError:
                    payload_future.cancel()
                    raise
                payload = await payload_future
                if (
                    realtime_lifecycle.drain_event.is_set()
                    or not realtime_lifecycle.accepting
                ):
                    return
                if payload["domains"] or payload["snapshot_required"]:
                    yield _sse("portal-change", payload)

def request_auth(method: str, params: Mapping[str, Any], *, socket_path: Path, actor: str = "") -> dict[str, Any]:
    key = load_rpc_signing_key(required=True, path=rpc_signing_key_file(socket_path=socket_path))
    return sign_rpc_auth(key, method, params, actor=actor)


class RpcAuthenticator:
    """One receiving service owns signature and replay validation for its socket."""

    def __init__(self, socket_path: Path, *, key: bytes | None = None):
        self.key = key if key is not None else load_rpc_signing_key(required=True, create=True,
                                        path=rpc_signing_key_file(socket_path=socket_path))
        self._lock = threading.Lock()
        self._nonces: OrderedDict[str, int] = OrderedDict()

    def authenticate(self, method: str, params: Mapping[str, Any], auth: object) -> str:
        actor, nonce, issued_at = verify_rpc_auth(self.key, method, params, auth)
        with self._lock:
            current = int(time.time())
            oldest = current - RPC_AUTH_MAX_AGE_SECONDS
            while self._nonces:
                first = next(iter(self._nonces))
                if self._nonces[first] >= oldest:
                    break
                self._nonces.popitem(last=False)
            if nonce in self._nonces:
                raise PermissionError("replayed Portal RPC authentication")
            self._nonces[nonce] = current
        return actor

    from management_common.authorization_context import current_subject

    params: dict[str, Any] = {"context": context.to_payload()}
    binding = current_subject()
    if binding is not None and binding.context.principal_id == context.caller:
        params["_authorization"] = binding.to_dict()
    return params


def _subject(params: dict[str, Any], context: InstructionContext, *, owner: str, verified_caller: str | None) -> Any:
    from management_common.authorization_context import SubjectBinding

    raw = params.get("_authorization")
    if raw is None:
        return None
    try:
        binding = SubjectBinding.from_dict(raw)
    except (TypeError, ValueError, PermissionError) as exc:
        raise InstructionError("instruction.forbidden", "授权主体无效") from exc
    if binding.context.principal_id != context.caller or verified_caller != context.caller:
        raise InstructionError("instruction.forbidden", "授权主体与调用者不一致")
    return binding


def _signed(owner: str, params: dict[str, Any], context: InstructionContext) -> dict[str, Any]:
    """Every owning service receives the authenticated entry's caller assertion."""
    from management_common.rpc_auth import request_auth

    return {"auth": request_auth(METHOD, params, socket_path=owner_socket(owner), actor=context.caller)}


def _open(owner: str, payload: dict[str, Any], timeout: float) -> tuple[socket.socket, Any]:
    connection: socket.socket | None = None
    try:
        # An owner that is restarting gets waited for, as a request to it has
        # not been sent yet.
        connection, _path = connect_service(owner_socket(owner), timeout=timeout)
        connection.sendall(
            json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8") + b"\n"
        )
    except OSError as exc:
        if connection is not None:
            connection.close()
        raise InstructionError(
            "instruction.owner_unavailable",
            f"拥有该指令的服务暂时不可用（{owner}）",
            details={"owner": owner},
            retryable=True,
            commit_state="not_committed",
        ) from exc
    return connection, connection.makefile("rb")


def _unavailable(owner: str, message: str) -> InstructionError:
    return InstructionError(
        "instruction.owner_unavailable",
        message,
        details={"owner": owner},
        retryable=True,
        commit_state="unknown",
    )


def _decode(owner: str, raw: bytes, request_id: str) -> dict[str, Any]:
    if not raw:
        raise _unavailable(owner, f"{owner} 关闭了连接，没有返回结果")
    try:
        response = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise _unavailable(owner, f"{owner} 返回了无法解析的结果") from exc
    if not isinstance(response, dict) or response.get("id") != request_id:
        raise _unavailable(owner, f"{owner} 返回了不匹配的响应")
    if not response.get("ok"):
        error = response.get("error") if isinstance(response.get("error"), dict) else {}
        raise InstructionError(
            str(error.get("code") or "instruction.failed"),
            str(error.get("message") or "指令执行失败"),
            details=error.get("details") if isinstance(error.get("details"), dict) else {},
            retryable=bool(error.get("retryable")),
            commit_state=str(error.get("commit_state") or "unknown"),
        )
    return response


def call_remote(
    owner: str, call: InstructionCall, context: InstructionContext, *, timeout: float = DEFAULT_TIMEOUT_SECONDS,
) -> InstructionResult:
    request_id = f"isa-{secrets.token_hex(10)}"
    params = request_params(call, context)
    payload = {"id": request_id, "method": METHOD, "params": params, **_signed(owner, params, context)}
    connection, stream = _open(owner, payload, timeout)
    try:
        try:
            raw = stream.readline()
        except (OSError, TimeoutError) as exc:
            raise _unavailable(owner, f"等待 {owner} 返回结果超时或连接中断") from exc
        response = _decode(owner, raw, request_id)
    finally:
        stream.close()
        connection.close()
    result = response.get("result")
    if not isinstance(result, dict):
        raise _unavailable(owner, f"{owner} 返回的结果格式无效")
    return InstructionResult.from_payload(result)

def handle(self) -> None:
    request_id = ""
    try:
        request = json.loads(self.rfile.readline())
        if not isinstance(request, dict):
            raise ValueError("request envelope must be an object")
        request_id = str(request.get("id") or "")
        params = request.get("params")
        if not isinstance(params, dict):
            raise ValueError("request params must be an object")
        method = str(request.get("method") or "")
        actor = self.server.rpc_auth.authenticate(method, params, request.get("auth"))
        if method == "instruction.execute":
            self.server.serve_instruction(params, request_id, self._write_line, verified_caller=actor)
            return
        from management_common.authorization_context import authorization_scope, SubjectBinding

        raw_subject = params.get("_authorization")
        binding = SubjectBinding.from_dict(raw_subject) if raw_subject is not None else None
        if binding is not None and binding.context.principal_id != actor:
            raise PermissionError("Authorization subject must match the authenticated RPC actor")
        with authorization_scope(binding):
            result = self.server.dispatch(method, params)
        response = {"id": request_id, "ok": True, "result": _json_value(result)}
    except Exception as exc:
        response = {"id": request_id, "ok": False, "error": _error_payload(exc)}
    try:
        self.wfile.write(
            json.dumps(
                response,
                ensure_ascii=False,
                separators=(",", ":"),
            ).encode("utf-8")
            + b"\n"
        )
    except (BrokenPipeError, ConnectionResetError):
        return

def _wait_healthy(
    instance: str,
    *,
    pids_before_restart: dict[str, int] | None = None,
    verify_components: tuple[str, ...] | list[str] | set[str] | None = None,
    worker_id_before_restart: str = "",
    timeout_seconds: float = 90,
) -> dict[str, Any]:
    deadline = time.monotonic() + timeout_seconds
    latest: dict[str, Any] = {}
    last_error = "services did not report healthy"
    while time.monotonic() < deadline:
        latest = instance_status(instance, include_schema=True)
        if latest.get("runtime_ok"):
            try:
                _assert_instance(
                    instance,
                    latest,
                    components=verify_components,
                )
                if worker_id_before_restart:
                    worker_health = latest.get("execution_worker") or {}
                    current = worker_health.get("current") or {}
                    worker_id = current.get("worker_id")
                    if (
                        not worker_health.get("ok")
                        or not worker_id
                        or worker_id == worker_id_before_restart
                    ):
                        raise RuntimeError("explicit Worker restart has not activated a new Worker")
                if pids_before_restart:
                    current = {
                        item["service"]: int(item["pid"])
                        for item in [latest["web_service"], *latest["services"]]
                    }
                    unchanged = {
                        service: pid
                        for service, pid in pids_before_restart.items()
                        if pid > 0 and current.get(service) == pid
                    }
                    if unchanged:
                        raise RuntimeError(f"service PIDs did not change: {unchanged}")
                return latest
            except RuntimeError as exc:
                last_error = str(exc)
        time.sleep(0.5)
    raise RuntimeError(
        f"{instance} failed post-start verification ({last_error}): {latest}"
    )

def read_restart_request(path: Path = REQUEST_PATH) -> dict[str, object]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(payload, dict) or payload.get("schema") != REQUEST_SCHEMA:
        return {}
    request_id = str(payload.get("request_id") or "").strip()
    components = payload.get("components")
    try:
        revision = int(payload.get("revision") or 0)
    except (TypeError, ValueError):
        return {}
    if not request_id or revision < 1 or not isinstance(components, list):
        return {}
    return {
        "schema": REQUEST_SCHEMA,
        "request_id": request_id,
        "revision": revision,
        "requested_at": str(payload.get("requested_at") or ""),
        "components": _normalized_components(components),
        "auto": bool(payload.get("auto", not components)),
    }


def submit_restart_request(
    components: Iterable[object],
    *,
    path: Path = REQUEST_PATH,
    lock_path: Path = REQUEST_LOCK_PATH,
) -> dict[str, object]:
    path.parent.mkdir(parents=True, exist_ok=True)
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("a+", encoding="utf-8") as stream:
        fcntl.flock(stream.fileno(), fcntl.LOCK_EX)
        existing = read_restart_request(path)
        submitted = _normalized_components(components)
        merged = _normalized_components([*(existing.get("components") or []), *submitted])
        request_id = str(existing.get("request_id") or "").strip()
        payload: dict[str, object] = {
            "schema": REQUEST_SCHEMA,
            "request_id": request_id or f"restart_request_{uuid.uuid4().hex}",
            "revision": int(existing.get("revision") or 0) + 1,
            "requested_at": datetime.now(timezone.utc).isoformat(),
            "components": merged,
            "auto": bool(existing.get("auto")) or not submitted,
        }
        atomic_replace_json(path, payload)
        return payload


def acknowledge_restart_request(
    request_id: object,
    revision: object,
    *,
    path: Path = REQUEST_PATH,
    lock_path: Path = REQUEST_LOCK_PATH,
) -> bool:
    target = str(request_id or "").strip()
    try:
        target_revision = int(revision)
    except (TypeError, ValueError):
        return False
    if not target or target_revision < 1:
        return False
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    with lock_path.open("a+", encoding="utf-8") as stream:
        fcntl.flock(stream.fileno(), fcntl.LOCK_EX)
        current = read_restart_request(path)
        if (
            str(current.get("request_id") or "") != target
            or int(current.get("revision") or 0) != target_revision
        ):
            return False
        try:
            path.unlink()
        except FileNotFoundError:
            return False
        return True

