def source_build_id(root: Path = ROOT) -> str:
    digest = hashlib.sha256()
    for path in source_paths(root):
        relative = path.relative_to(root).as_posix()
        digest.update(relative.encode("utf-8"))
        digest.update(b"\0")
        try:
            digest.update(path.read_bytes())
        except FileNotFoundError:
            continue
        digest.update(b"\0")
    return f"dev-{digest.hexdigest()[:16]}"


def read_build_id(path: Path = DEV_GENERATION_ENV) -> str:
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return ""
    for line in lines:
        key, separator, value = line.partition("=")
        if separator and key.strip() == "PORTAL_BUILD_ID":
            return value.strip()
    return ""


def read_component_build_ids(
    path: Path = DEV_COMPONENT_GENERATIONS,
) -> dict[str, str]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    values = payload.get("components") if isinstance(payload, dict) else {}
    if not isinstance(values, dict):
        return {}
    return {
        str(component): str(build_id)
        for component, build_id in values.items()
        if str(component) in COMPONENTS and str(build_id)
    }


def _write_component_build_ids(
    values: dict[str, str],
    path: Path = DEV_COMPONENT_GENERATIONS,
) -> None:
    atomic_replace_json(
        path,
        {"schema": "tfi.portal-component-generations.v1", "components": values},
    )


def activate(
    root: Path = ROOT,
    path: Path = DEV_GENERATION_ENV,
    *,
    components: tuple[str, ...] | list[str] | None = None,
) -> str:
    build_id = source_build_id(root)
    previous_build_id = read_build_id(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    temporary.write_text(f"PORTAL_BUILD_ID={build_id}\n", encoding="utf-8")
    os.replace(temporary, path)
    selected = COMPONENTS if components is None else tuple(components)
    unknown = sorted(set(selected) - set(COMPONENTS))
    if unknown:
        raise ValueError(f"unknown Portal components: {unknown}")
    component_path = path.with_name(DEV_COMPONENT_GENERATIONS.name)
    values = read_component_build_ids(component_path)
    if not values:
        values = {
            component: previous_build_id or build_id
            for component in COMPONENTS
        }
    for component in selected:
        values[component] = build_id
    _write_component_build_ids(values, component_path)
    return build_id

DDL = '''CREATE TABLE IF NOT EXISTS publications (
    sequence BIGSERIAL PRIMARY KEY,
    publication_key TEXT UNIQUE NOT NULL,
    commit_id TEXT NOT NULL,
    completed_at TIMESTAMPTZ NOT NULL,
    previous_commit TEXT NOT NULL DEFAULT '',
    source TEXT NOT NULL DEFAULT ''
);
ALTER TABLE publications ADD COLUMN IF NOT EXISTS previous_commit TEXT NOT NULL DEFAULT '';
ALTER TABLE publications ADD COLUMN IF NOT EXISTS source TEXT NOT NULL DEFAULT '';
'''


@lru_cache(maxsize=8)
def _domain(dsn, namespace):
    return DomainDatabase('portal_release_events', 'publisher', DDL)


def domain():
    return _domain(os.getenv('PORTAL_DATABASE_URL'), os.getenv('PORTAL_DATABASE_NAMESPACE'))


def record(result):
    if result.get('status') != 'completed' or result.get('ok') is not True:
        raise ValueError('only a healthy completed local publication is a fact')
    commit = result['commit']
    if not re.fullmatch(r'[0-9a-f]{40}', commit) or result.get('active_commit') != commit:
        raise ValueError('publication commit must be the active Release commit')
    key = hashlib.sha256(f"{commit}:{result['started_at']}".encode()).hexdigest()
    # Serializing allocation and commit keeps sequence order equal to commit
    # order; a reader cannot skip a lower sequence still in flight.
    with domain().transaction('append') as connection:
        row = connection.execute('''INSERT INTO publications
            (publication_key,commit_id,completed_at,previous_commit,source)
            VALUES (%s,%s,%s,%s,%s) ON CONFLICT(publication_key) DO UPDATE
            SET publication_key=EXCLUDED.publication_key RETURNING sequence''',
            (key, commit, instant(result['completed_at']), result.get('parent_commit', ''),
             result.get('origin', ''))).fetchone()
    return int(row['sequence'])


def latest_sequence():
    with domain().read() as connection:
        row = connection.execute('SELECT COALESCE(MAX(sequence),0) AS sequence FROM publications').fetchone()
    return int(row['sequence'])


def after(sequence, limit=100, *, latest_only=False):
    order = 'DESC' if latest_only else 'ASC'
    with domain().read() as connection:
        rows = connection.execute(f'''SELECT sequence,publication_key,commit_id,completed_at,previous_commit,source FROM publications
            WHERE sequence>%s ORDER BY sequence {order} LIMIT %s''',
            (sequence, 1 if latest_only else limit)).fetchall()
    return [{'sequence': int(row['sequence']), 'publication_id': row['publication_key'],
             'commit': row['commit_id'], 'previous_commit': row['previous_commit'], 'source': row['source'],
             'completed_at': iso_time(row['completed_at'])} for row in rows]

def prefetch(lineage_id, plan):
    sources = {key: source for key, source in plan.get('event_sources', {}).items()
               if source.get('event_type') == EVENT}
    if not sources:
        return {}
    runtime = lineage_program_runtime.read_runtime(lineage_id).get('event_sources', {})
    latest = portal_release_events.latest_sequence()
    result = {}
    for key, source in sources.items():
        state = runtime.get(key, {})
        previous = state.get('state_value', '')
        if state.get('state_locator') != LOCATOR or not previous.startswith('publication:'):
            result[key] = {'baseline': latest, 'records': [], 'previous': ''}
        else:
            sequence = int(previous.split(':')[1])
            result[key] = {'baseline': None, 'records': portal_release_events.after(
                sequence, latest_only=source.get('misfire_policy') == 'coalesce_latest'),
                           'previous': state.get('state_signature', '')}
    return result


def pending(source_id, source, batch, fingerprint):
    previous = batch['previous']
    result = []
    for record in batch['records']:
        signature = value(record['sequence'])
        result.append({'event_source_id': source_id,
            'event': lineage_primitives.make_event(EVENT, payload=record,
                correlation=signature, occurred_at=record['completed_at']),
            'cursor': signature, 'source_contract': fingerprint(source),
            'state_locator': LOCATOR, 'previous_state_signature': previous,
            'state_signature': signature, 'state_value': signature})
        previous = signature
    return result

def audit(repo, mapping, spec, improve, evolution, documents, instructions, read_errors=None,
          resolve_resource=None):
    findings = []
    external_references, reference_cache = [], {}

    def note(code, subject, **details):
        findings.append(dict(code=code, subject=subject, **details))

    if mapping.get('schema') != SCHEMA:
        raise ValueError('unsupported module map schema')
    model_version = mapping.get('model_version', 1)
    if model_version not in (1, 2):
        raise ValueError('unsupported module model version')
    runtime_model = model_version == 2
    modules = mapping['modules']
    protocols = mapping.get('protocols', [])
    ids = [m['id'] for m in modules]
    by_id = {m['id']: m for m in modules}
    for mid, count in Counter(ids).items():
        if count != 1:
            note('module.duplicate', mid, count=count)
    owners, designs = defaultdict(list), defaultdict(list)
    protocol_by_id = {p['id']: p for p in protocols}

    def contains(endpoint, module):
        seen = set()
        while module in by_id and module not in seen:
            if endpoint == module:
                return True
            seen.add(module)
            module = by_id[module].get('parent')
        return False

    def evidence(edge):
        return edge.get('designs', []) + (edge.get('related_designs', []) if runtime_model else [])

    def has_protocol(design, owner, other):
        return any(design in evidence(edge)
                   and any(contains(endpoint, owner) for endpoint in edge.get('modules', []))
                   and any(contains(endpoint, other) for endpoint in edge.get('modules', []))
                   for edge in protocols)
    for m in modules:
        mid = m['id']
        if m.get('parent') and (m['parent'] not in by_id or by_id[m['parent']].get('parent')):
            note('module.invalid_parent', mid, parent=m['parent'])
        for owner in m.get('instruction_owners', []):
            owners[owner].append(mid)
        for design in m.get('designs', []):
            designs[design].append(('module', mid))
        if runtime_model:
            if m.get('layer') not in {'frontend', 'entry', 'service', 'storage', 'external'}:
                note('module.invalid_layer', mid, layer=m.get('layer'))
            if m.get('level') not in {'runtime', 'component', 'external'}:
                note('module.invalid_level', mid, level=m.get('level'))

def run(repo, call):
    inputs = {name: repo.read(name) for name in ('SPEC.md', 'IMPROVE.md', 'architecture/modules.yaml')}
    mapping = yaml.safe_load(inputs['architecture/modules.yaml'])
    evolution = None
    if repo.exists('architecture/evolution.yaml'):
        inputs['architecture/evolution.yaml'] = repo.read('architecture/evolution.yaml')
        evolution = yaml.safe_load(inputs['architecture/evolution.yaml'])
    spec = indexed_ids(inputs['SPEC.md'], 'decision')
    improve = indexed_ids(inputs['IMPROVE.md'], 'plan')
    addresses = sorted(set(spec) | {p['id'] for p in (evolution or {}).get('plans', [])})
    docs, versions, errors = {}, {}, {}

    def read(address):
        try:
            result = call('ReadResource', {'address': address})
            text = result['text']
            meta = metadata(text)
            if meta.get('kb_id') != address:
                raise ValueError('resource identity mismatch')
            content_version = (meta.get('version') or {}).get('number')
            return address, meta, {'version': str(content_version if content_version is not None else result['version']),
                                   'response_version': result['version'],
                                   'sha256': hashlib.sha256(text.encode()).hexdigest()}, ''
        except Exception as exc:
            # Do not echo response bodies or credentials into operational artifacts.
            return address, None, None, error_code(exc)

    with ThreadPoolExecutor(max_workers=6) as pool:
        for address, meta, version, error in pool.map(read, addresses):
            if error:
                errors[address] = error
            else:
                docs[address], versions[address] = meta, version
    instructions = call('ListInstructions', {})['instructions']
    report = audit(repo, mapping, spec, improve, evolution, docs, instructions, errors,
                   resolve_resource=lambda address: call('ResolveResource', {'address': address}))
    report['sources'] = {'files': {name: hashlib.sha256(text.encode()).hexdigest() for name, text in inputs.items()},
                         'resources': versions, 'instruction_catalog_sha256': hashlib.sha256(
                             json.dumps(instructions, sort_keys=True, ensure_ascii=False).encode()).hexdigest()}
    if not repo.commit and any(repo.read(name) != text for name, text in inputs.items()):
        report['audit_failed'] = True
        report['findings'].append({'code': 'input.changed_during_audit', 'subject': 'working_tree'})
        report['counts']['deviations'] += 1
        report['by_code']['input.changed_during_audit'] = 1
    return report


def report_markdown(report):
    summary = ['# Portal 架构核对', '', f"代码版本：{report.get('commit') or 'Dev 工作树'}", '',
               f"核对完整：{not report['audit_failed']}；偏离：{report['counts']['deviations']}", '']
    summary += [f'- `{code}`：{count}' for code, count in report['by_code'].items()]
    summary += ['', '## 外部引用清单', '', '不参与实现归属检查；URL 只验证格式，不宣称远端可达。', '']
    for ref in report.get('external_references', []):
        target = json.dumps(ref['reference'], ensure_ascii=False)
        summary.append(f"- `{ref['design']}` · {ref['kind']} · {ref['status']} · {target}")
    summary += ['', '逐项路径、引用检查、资源版本与内容摘要见 architecture-audit.json。', '']
    return '\n'.join(summary)


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--repo-root', type=Path, default=ROOT)
    parser.add_argument('--commit', default='')
    parser.add_argument('--resident-id', default=os.environ.get('PORTAL_RESIDENT_ID', ''))
    parser.add_argument('--output-dir', type=Path)
    args = parser.parse_args(argv)
    input_fields = {}
    if os.environ.get('PORTAL_SCRIPT_INPUT'):
        from portal_script import inputs
        input_fields = inputs().get('arguments', {})
    commit = args.commit or input_fields.get('commit', '')
    destination = args.output_dir or Path(os.environ.get('PORTAL_SCRIPT_ARTIFACTS', '.'))
    destination.mkdir(parents=True, exist_ok=True)
    try:
        report = run(Repository(args.repo_root, commit), isa_client(args.resident_id))
    except Exception as exc:
        report = {'schema': 'tfi.portal-architecture-audit.v1', 'commit': commit,
                  'audit_failed': True, 'counts': {'deviations': 1},
                  'by_code': {'audit.failed': 1},
                  'findings': [{'code': 'audit.failed', 'subject': type(exc).__name__}]}
    (destination / 'architecture-audit.json').write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n')
    (destination / 'architecture-audit.md').write_text(report_markdown(report))
    output = {'has_deviations': bool(report['counts']['deviations']), 'audit_failed': report['audit_failed'],
              'commit': commit, 'counts': report['counts'], 'by_code': report['by_code'],
              'report': 'architecture-audit.json'}
    if os.environ.get('PORTAL_SCRIPT_OUTPUT'):
        from portal_script import set_output
        set_output(output)
    print(json.dumps(output, ensure_ascii=False))
    return 2 if report['audit_failed'] else 0

def source_digests(case_id: str, implementation: dict[str, Any], root: Path = ROOT) -> dict[str, str]:
    """Freeze the source file and, for declarative TAU, the selected case's semantics."""
    source = str(implementation['source'])
    path = (root / source).resolve(strict=False)
    if root.resolve() not in path.parents or not path.is_file():
        raise CatalogError(f"测试实现源码不可用：{source}")
    try:
        content = path.read_bytes()
        digests = {'source_sha256': hashlib.sha256(content).hexdigest()}
        if implementation.get('runner') != 'tau' or path.suffix != '.json':
            return digests
        document = json.loads(content)
        if document.get('schema') not in {'tfi.portal-tau-cases.v1', 'tfi.portal-spec-design-cases.v1'}:
            raise ValueError('unknown TAU source schema')
        matches = [case for case in document['cases'] if case['id'] == case_id]
        if len(matches) != 1:
            raise ValueError('TAU case must have one declaration')
        case = matches[0]
        implementations = case['implementations']
        selected = [item for item in implementations if item['id'] == implementation['id']]
        if len(selected) != 1 or Implementation.parse(selected[0], case_id).public() != implementation:
            raise ValueError('catalog and TAU implementation differ')
        # A generated source line and other cases are not this declaration's semantics.
        case = {**case, 'implementations': [
            {key: value for key, value in item.items() if key != 'line'} for item in implementations
        ]}
        snapshot = {key: value for key, value in document.items() if key != 'cases'}
        snapshot['cases'] = [case]
        encoded = json.dumps(snapshot, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode()
        digests['source_case_sha256'] = hashlib.sha256(encoded).hexdigest()
        return digests
    except (OSError, ValueError, TypeError, KeyError, AttributeError) as exc:
        raise CatalogError(f"测试实现源码声明不可用或与目录不一致：{source} / {case_id}") from exc


def planned_source_changed(item: dict[str, Any], root: Path = ROOT) -> bool:
    """Check the plan's recorded scope; old plans retain their whole-file contract."""
    implementation = item['implementation']
    if 'source_case_sha256' in item:
        try:
            actual = source_digests(item['case_id'], implementation, root)
        except CatalogError:
            return True
        return actual.get('source_case_sha256') != item['source_case_sha256']
    path = (root / str(implementation['source'])).resolve(strict=False)
    actual = hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() and root.resolve() in path.parents else ''
    return actual != item.get('source_sha256')

"""Return every valid case while isolating malformed catalog entries."""
with self._lock:
    revision = self._projection_revision()
    if revision == self._projection_cache_revision and self._projection_cache is not None:
        cached_cases, cached_errors = self._projection_cache
        return cached_cases, [
            {"resource_id": resource_id, "error": error}
            for resource_id, error in cached_errors
        ]
    raw = self._read()
    edits = self._edits()
    cases: list[TestCase] = []
    errors: list[dict[str, str]] = []
    raw_ids: dict[str, int] = {}
    for item in raw.get("cases", []):
        raw_id = str(item.get("id") or "") if isinstance(item, dict) else ""
        if raw_id:
            raw_ids[raw_id] = raw_ids.get(raw_id, 0) + 1
        try:
            if not isinstance(item, dict):
                raise CatalogError("测试用例必须是对象")
            cases.append(TestCase.parse({**item, **edits.get(raw_id, {})}))
        except (CatalogError, TypeError, ValueError) as exc:
            errors.append({"resource_id": raw_id, "error": str(exc)[:1000]})
    conflicts: dict[str, list[TestCase]] = {}
    for case in cases:
        keys = [f"ID:{case.id}", f"key:{case.key}"]
        if case.design_point_ref:
            keys.append(f"设计点:{case.design_point_ref}")
        for impl in case.implementations:
            keys.extend((f"实现ID:{impl.id}", f"实现入口:{impl.entrypoint}"))
        for key in keys:
            conflicts.setdefault(key, []).append(case)
    blocked: dict[str, str] = {key: "测试用例 ID 重复" for key, count in raw_ids.items() if count > 1}
    for key, owners in conflicts.items():
        if len(owners) > 1:
            blocked.update({case.id: f"测试定义重复：{key}" for case in owners})
    sources: dict[str, set[str] | Exception] = {}
    if self.verify_sources:
        for case in cases:
            for impl in case.implementations:
                if impl.runner not in {"pytest", "browser-script"}:
                    continue
                if impl.source not in sources:
                    try:
                        path = (ROOT / impl.source).resolve()
                        sources[impl.source] = source_entrypoints(path)
                    except (OSError, SyntaxError, ValueError) as exc:
                        sources[impl.source] = exc
                entries = sources[impl.source]
                if isinstance(entries, Exception) or impl.entrypoint not in entries:
                    blocked[case.id] = f"测试实现源码不可用或入口已失效：{impl.entrypoint}"
    errors.extend({"resource_id": key, "error": value} for key, value in blocked.items())
    projected = tuple(case for case in cases if case.id not in blocked)
    cached_errors = tuple(
        (str(item.get("resource_id") or ""), str(item.get("error") or ""))
        for item in errors
    )
    self._projection_cache_revision = revision
    self._projection_cache = (projected, cached_errors)
    return projected, [
        {"resource_id": resource_id, "error": error}
        for resource_id, error in cached_errors
    ]

        if not isinstance(fail_fast, bool):
            raise CatalogError("fail_fast 必须是布尔值")
        if resident_runtime and not resident_account:
            raise CatalogError("resident_runtime 需要同时指定 resident_account_id")
        selected_runners = set(runner_ids(implementation.get("runners")))
        implementation_ids = set(clean_list(implementation.get("implementation_ids")))
        profile_id = str(implementation.get("profile") or "").strip()
        profile = None
        if profile_id:
            profile = self.registry.profile(profile_id)
        cases = self.catalog.query(selection)
        selected: list[dict[str, Any]] = []
        excluded: list[dict[str, str]] = []
        for case in cases:
            compatible = []
            for item in case.implementations:
                if implementation_ids and item.id not in implementation_ids:
                    continue
                if selected_runners and item.runner not in selected_runners:
                    continue
                descriptor = self.registry.runner(item.runner)
                if not descriptor.available:
                    continue
                if profile_id and profile_id not in item.profiles:
                    continue
                compatible.append(item)
            if not compatible:
                excluded.append({"case_id": case.id, "title": case.display_title(), "reason": "no-compatible-implementation"})
                continue
            for item in compatible:
                selected.append(
                    {
                        "case_id": case.id,
                        "case_title": case.display_title(),
                        "description": case.display_description(),
                        "importance": case.importance,
                        "module": case.module,
                        "aspects": list(case.aspects),
                        "is_design_point": case.is_design_point,
                        "implementation": item.public(),
                        "runner": self.registry.runner(item.runner).public(),
                        "profile": profile_id,
                        # The implementation owns execution side effects. A Profile
                        # contributes a separate environment risk instead of hiding
                        # an undeclared implementation behind a Profile label.
                        "risk": item.risk,
                        "profile_risk": profile.risk if profile else "",
                        **source_digests(case.id, item.public(), ROOT),
                        **({"resident_account_id": resident_account} if resident_account else {}),
                        **({"resident_runtime": resident_runtime} if resident_runtime else {}),
                    }
                )
        groups: list[dict[str, Any]] = []
        is_tau_campaign = bool(selected) and all(
            item["runner"]["id"] == TAU_RUNNER_ID for item in selected
        )
        if (resident_account or parallel_modules is not None) and not is_tau_campaign:
            raise CatalogError("Resident 账号与模块并发设置仅用于 TAU Campaign")
        if fail_fast and is_tau_campaign:
            raise CatalogError("fail_fast 仅用于本地运行；TAU Campaign 总是继续执行其他用例")
        if not is_tau_campaign and any(item["runner"]["id"] == TAU_RUNNER_ID for item in selected):
            # TAU is a live Campaign on DEV with its own Residents; a local
            # run executes pytest and Playwright only.
            local_cases = {item["case_id"] for item in selected if item["runner"]["id"] != TAU_RUNNER_ID}
            for item in selected:
                if item["runner"]["id"] == TAU_RUNNER_ID and item["case_id"] not in local_cases:
                    local_cases.add(item["case_id"])
                    excluded.append({"case_id": item["case_id"], "title": item["case_title"], "reason": "tau-campaign-only"})
            selected = [item for item in selected if item["runner"]["id"] != TAU_RUNNER_ID]
        if is_tau_campaign:
            for module_id in dict.fromkeys(item["module"] for item in selected):
                groups.append({
                    "group_id": f"module:{module_id}",
                    "module_id": module_id,
                    "runner": TAU_RUNNER_ID,
                    "item_indexes": [
                        index for index, item in enumerate(selected)
                        if item["module"] == module_id
                    ],
                    "continue_on_failure": True,
                })
        elif selected:
            groups = plan_groups(selected, continue_on_failure=not fail_fast)
        normalized_implementation = {
            **implementation,
            **({"runners": list(runner_ids(implementation.get("runners")))} if implementation.get("runners") else {}),
        }
        execution = {
            "mode": "parallel-modules" if is_tau_campaign else "batch",
            "groups": groups,
            **(
                {"max_parallel_modules": parallel_modules if parallel_modules is not None else tau_max_parallel_modules()}
                if is_tau_campaign
                else {}
            ),
        }
        identity = json.dumps({"selection": selection, "implementation": normalized_implementation, "selected": selected, "execution": execution}, sort_keys=True, ensure_ascii=False)
        return {
            "schema": "tfi.source-author-run-plan.v2",
            "plan_id": f"plan-{hashlib.sha256(identity.encode()).hexdigest()[:16]}",
            "request": {"select": selection, "implementation": normalized_implementation},
            "selected": selected,
            "excluded": excluded,
            "selected_case_count": len({item["case_id"] for item in selected}),
            "selected_implementation_count": len(selected),
            "execution": execution,
            "campaign": "tau" if is_tau_campaign else "",
            "executable": bool(selected),
        }


