class RunCoordinator:
    """Owns the run lifecycle in the Portal process: create, launch, read, cancel, delete.

    Every run executes in its own Test executor unit (``tests.framework.executor``):
    local runs as sandboxed batches, TAU Campaigns against the real DEV. This
    process starts the unit through ``launch`` and afterwards only reads and
    annotates the run's records, so restarting it never stops a run.
    """

    def __init__(
        self,
        records: RunRecords,
        run_root: Path,
        *,
        launch: Callable[[str], None] | None = None,
    ):
        self.records = records
        self.run_root = run_root
        self.launch = launch or self._launch_unit
        self._lock = threading.Lock()
        self._launched_at: dict[str, float] = {}

    def _launch_unit(self, run_id: str) -> None:
        from tests.framework.executor import launch_unit

        launch_unit(run_id, self.records.path.parent, tau=is_tau_run(self.records.get(run_id)))

    def start(self, plan: dict[str, Any], actor: str) -> dict[str, Any]:
        if not plan.get("executable") or not plan.get("selected"):
            raise ValueError("运行计划没有可执行的测试实现")
        if is_tau_run({"plan": plan}):
            from management_portal.society_service.application_target_configuration import admission_scope

            # The shared admission lock covers durable acceptance. A freeze
            # waits for this record, while already accepted executors may run.
            with admission_scope("tau"):
                record = self.records.create(plan, actor)
        else:
            record = self.records.create(plan, actor)
        self.remove_orphan_artifacts()
        try:
            self.launch(record["run_id"])
        except Exception as exc:
            return self.records.update(record["run_id"], {
                "status": "error", "error": str(exc), "finished_at": now_iso(),
            })
        return record

    def remove_orphan_artifacts(self) -> list[str]:
        """Remove evidence whose record is gone; active runs are always retained."""
        known = self.records.run_ids()
        try:
            entries = list(self.run_root.iterdir())
        except FileNotFoundError:
            return []
        removed = []
        for path in entries:
            if path.name.startswith("testrun_") and path.name not in known and path.is_dir() and not path.is_symlink():
                shutil.rmtree(path, ignore_errors=True)
                removed.append(path.name)
        return removed

    def recover(self, run_ids: set[str] | None = None) -> list[str]:
        """Close local runs whose executor is gone and relaunch an executor for every other unowned run.

        Runs once when Web starts (after a host restart no unit survives) and
        whenever a reader finds a run without a live executor. A relaunched
        executor takes a TAU Campaign over; the unit name admits one executor
        per run, so a launch for a run whose unit is still active fails harmlessly.
        """
        self.records.recover_interrupted(run_ids)
        launched = []
        for run_id in self.records.unowned(run_ids):
            now = time.monotonic()
            with self._lock:
                last = self._launched_at.get(run_id)
                if last is not None and now - last < RELAUNCH_SECONDS:
                    continue
                self._launched_at[run_id] = now
            try:
                self.launch(run_id)
            except Exception as exc:  # noqa: BLE001 - a later reader retries
                LOGGER.warning("Test executor relaunch failed for %s: %s", run_id, exc)
                continue
            launched.append(run_id)
        return launched

    def get(self, run_id: str, actor: str) -> dict[str, Any]:
        if not actor:
            raise PermissionError("需要已认证用户")
        record = self.records.get(run_id)
        if record.get("status") not in TERMINAL and not _executor_alive(record):
            self.recover({run_id})
            record = self.records.get(run_id)
        return record

    def cancel(self, run_id: str, actor: str) -> dict[str, Any]:
        record = self.get(run_id, actor)
        if record.get("created_by") != actor:
            raise PermissionError("只有运行发起者可以取消测试运行")
        if record.get("status") in TERMINAL:
            return record
        # The executor sees the persisted request and stops its work.
        return self.records.request_cancel(run_id)

def unit_name(run_id: str) -> str:
    return UNIT_PREFIX + run_id.removeprefix("testrun_")


def postgres_environment_file() -> str:
    return os.getenv("PORTAL_POSTGRES_ENV_FILE", "/srv/tfi/.config/tfi/portal-postgres.env")


def unit_environment(state_root: Path, *, tau: bool) -> dict[str, str]:
    """The environment of an executor unit; it never carries a secret.

    A TAU Campaign gets the Portal service routing and test settings of the
    launching process; the unit reads the database URL from the PostgreSQL
    environment file, so the URL never appears in a command line.
    """
    environment = {
        "PORTAL_TEST_FRAMEWORK_STATE_ROOT": str(state_root),
        "PORTAL_INSTANCE": instance_name(),
        **{
            key: os.environ[key]
            for key in ("PATH", "PORTAL_TEST_STORAGE_STATE", "PORTAL_TEST_SLOT_ROOT", "PORTAL_TEST_MAX_CONCURRENCY")
            if os.environ.get(key)
        },
    }
    if tau:
        environment.update({
            key: value for key, value in os.environ.items()
            if key.startswith("PORTAL_") and value and not SECRET_NAME.search(key) and key not in environment
        })
        for key, value in SERVICE_ROUTING.items():
            environment.setdefault(key, value)
    return environment


def launch_unit(run_id: str, state_root: Path, *, tau: bool = False) -> None:
    """Start the executor for one run as a transient systemd user unit."""
    command = [
        "systemd-run", "--user", "--collect", "--quiet", f"--unit={unit_name(run_id)}",
        # Tests yield to Portal under contention instead of sharing CPU equally.
        "--property=CPUWeight=20", "--property=IOWeight=20", "--nice=10",
        "--property=TasksMax=4096", "--property=KillMode=control-group", "--property=TimeoutStopSec=15",
        # A TAU Campaign lasts as long as its cases; a local run is bounded.
        "--property=RuntimeMaxSec=" + ("infinity" if tau else "28800"),
        *(["--property=EnvironmentFile=" + postgres_environment_file()] if tau else []),
        f"--working-directory={ROOT}",
        *(f"--setenv={key}={value}" for key, value in unit_environment(state_root, tau=tau).items()),
        sys.executable, "-m", "tests.framework.executor", "--state-root", str(state_root), run_id,
    ]
    result = subprocess.run(command, capture_output=True, text=True, timeout=30, check=False)
    if result.returncode:
        raise RuntimeError("测试执行单元启动失败：" + (result.stderr or result.stdout)[-2000:])

def _is_cancelled(self, run_id: str) -> bool:
    # Web persists a cancellation in the record; this process only reads it.
    try:
        return self.records.get(run_id).get("status") == "cancelling"
    except (KeyError, RuntimeError):
        return False

@staticmethod
def _verify_source(item: dict[str, Any]) -> None:
    if planned_source_changed(item):
        raise RuntimeError(f"运行计划对应的源码已变化：{item['implementation']['source']}")

def _execute_group_with_slot(
    self, run_id: str, group_spec: dict[str, Any], selected: list[dict[str, Any]],
    run_dir: Path, actor: str,
) -> tuple[str, str]:
    group_id = str(group_spec["group_id"])
    self.records.update_group(run_id, group_id, {"status": "queued"})
    # Every campaign uses the same Resident for a module. Keep its entire
    # invocation and cleanup together, even when several campaigns run.
    def reserved():
        holders = self.records.invocation_holders()
        if (run_id, group_id) in holders:
            return False
        # A saved invocation outlives its executor's file locks. Resume it
        # before sending a fresh case to that Resident or taking capacity
        # needed by a queued resumption in another module.
        return any(owner_group == group_id or status == "queued"
                   for (_, owner_group), status in holders.items())

    while True:
        if (self._is_cancelled(run_id)
                and (run_id, group_id) not in self.records.invocation_holders()):
            self.records.update_group(run_id, group_id, {"status": "cancelled"})
            return "cancelled", ""
        if reserved():
            time.sleep(1)
            continue
        with slots.exclusive(f"tau-module:{group_spec['module_id']}",
                             stop=lambda: self._is_cancelled(run_id) or reserved()) as acquired:
            if not acquired or reserved():
                continue
            try:
                self._recover_module_cleanup(run_id, group_id)
            except Exception as exc:
                error = f"前次 TAU 资源清理尚未完成：{exc}"
                self.records.update_group(run_id, group_id, {"status": "error", "error": error})
                return "error", error
            return self._execute_group_in_slot(run_id, group_spec, selected, run_dir, actor)

def configuration_binding(application: str) -> tuple[str, str, str | int, str]:
    """Resolve the closed application vocabulary to its existing owned row."""
    if application == "tau":
        return "tau_configuration", "singleton", 1, "lineage_id"
    if application in {"resident_discovery", "resident_summary", "notice_classifier", "discussion_reply"}:
        return application + "_configuration", "singleton", 1, "resident_id"
    prefix, _, value = str(application).partition(":")
    if prefix == "semantic_search" and value in SEARCH_SURFACES:
        return "semantic_search_residents", "surface", value, "resident_id"
    if prefix == "resource_chat" and value in CHAT_TYPES:
        return "resource_chat_lineages", "resource_type", value, "lineage_id"
    raise ValueError("Unknown application target")


class ApplicationUnconfigured(OperationError, LookupError):
    code = "instruction.not_found"
    http_status = 404
    commit_state = "not_committed"


def create_schema(connection) -> None:
    for table in ("resident_discovery_configuration", "resident_summary_configuration", "notice_classifier_configuration", "discussion_reply_configuration"):
        connection.execute(f"CREATE TABLE {table} (singleton INTEGER PRIMARY KEY CHECK(singleton=1), resident_id TEXT NOT NULL REFERENCES residents(resident_id),{CONFIGURATION_DDL})")
    connection.execute(f"CREATE TABLE semantic_search_residents (surface TEXT PRIMARY KEY CHECK(surface IN {SEARCH_SURFACES}), resident_id TEXT NOT NULL REFERENCES residents(resident_id),{CONFIGURATION_DDL})")
    connection.execute(f"CREATE TABLE resource_chat_lineages (resource_type TEXT PRIMARY KEY CHECK(resource_type IN {CHAT_TYPES}), lineage_id TEXT NOT NULL REFERENCES lineages(lineage_id),{CONFIGURATION_DDL})")
    connection.execute(f"CREATE TABLE tau_configuration (singleton INTEGER PRIMARY KEY CHECK(singleton=1),lineage_id TEXT NOT NULL REFERENCES lineages(lineage_id),{CONFIGURATION_DDL})")


def _target(table: str, key: str, value, *, field: str) -> str:
    return _target_record(table, key, value, field=field)[field]


def _target_record(table: str, key: str, value, *, field: str) -> dict[str, str]:
    # Readers of application configuration do not initialize or migrate the
    # entire Lineage schema. Long-lived callers can span an owner deployment.
    with portal_database(schema="lineage").read() as connection:
        identity_table, identity_column = ("lineages", "lineage_id") if field == "lineage_id" else ("residents", "resident_id")
        if field == "lineage_id":
            columns, membership, active = "i.lineage_id", "", ""
        else:
            columns = "i.resident_id, n.lineage_id"
            membership = "JOIN lineage_nodes n ON n.node_id=i.resident_id JOIN lineages l ON l.lineage_id=n.lineage_id "
            active = " AND n.node_type='resident' AND n.deleted_at IS NULL AND l.deleted_at IS NULL"
        row = connection.execute(
            f"SELECT {columns} FROM {table} t JOIN {identity_table} i ON i.{identity_column}=t.{field} "
            f"{membership}WHERE t.{key}=%s AND i.deleted_at IS NULL{active}", (value,),
        ).fetchone()
    if not row:
        raise ApplicationUnconfigured(f"Application target is not configured: {table}/{value}")
    return {key: str(value) for key, value in dict(row).items()}

def _row(connection, binding, *, lock: str = ""):
    table, key, value, field = binding
    return connection.execute(
        f"SELECT {field} AS target_id,{','.join(CONFIGURATION_COLUMNS)} FROM {table} WHERE {key}=%s" + lock,
        (value,),
    ).fetchone()


def _available(connection, binding, target_id: str, *, lock: bool = False) -> bool:
    if not target_id:
        return False
    if binding[3] == "lineage_id":
        query = "SELECT lineage_id FROM lineages WHERE lineage_id=%s AND deleted_at IS NULL"
    else:
        query = ("SELECT r.resident_id FROM residents r JOIN lineage_nodes n ON n.node_id=r.resident_id "
                 "JOIN lineages l ON l.lineage_id=n.lineage_id WHERE r.resident_id=%s "
                 "AND r.deleted_at IS NULL AND n.deleted_at IS NULL AND n.node_type='resident' AND l.deleted_at IS NULL")
    return bool(connection.execute(query + (" FOR SHARE" if lock else ""), (target_id,)).fetchone())


def _view(connection, application, binding, row) -> dict:
    value = dict(row) if row else {
        "target_id": "", "revision": 0, "admission_paused": False,
        "reason": "", "updated_by": "", "updated_at": "",
    }
    value["target_available"] = _available(connection, binding, value["target_id"])
    value["admission_state"] = (
        "paused" if value["admission_paused"] else "open" if value["target_available"] else "unconfigured"
    )
    return {"schema": "tfi.application-target.v1", "application": application,
            "supports_admission_pause": application == "tau", **value}


def get(application: str, actor: str) -> dict:
    _admin(actor)
    binding = configuration_binding(application)
    with portal_database(schema="lineage").read() as connection:
        return _view(connection, application, binding, _row(connection, binding))

def update(application: str, changes: dict, actor: str, *, expected_revision: int) -> dict:
    _admin(actor)
    binding = configuration_binding(application)
    if type(expected_revision) is not int or expected_revision < 0:
        raise ValueError("expected_revision must be a nonnegative integer")
    if not isinstance(changes, dict) or not changes or set(changes) - {"target_id", "admission_paused", "reason"}:
        raise ValueError("changes requires target_id, admission_paused or reason")
    if "admission_paused" in changes:
        if type(changes["admission_paused"]) is not bool:
            raise ValueError("admission_paused must be boolean")
        if application != "tau":
            raise ConfigurationConflict("This application does not support admission controls")
    if "reason" in changes and (not isinstance(changes["reason"], str) or len(changes["reason"]) > 1000):
        raise ValueError("reason must be text of at most 1000 characters")
    if "target_id" in changes and (
        not isinstance(changes["target_id"], str) or
        not re.fullmatch(binding[3].removesuffix("_id") + r"_[0-9a-f]{12}", changes["target_id"])
    ):
        raise ValueError("target_id must match the application's target type")
    with portal_database(schema="lineage").transaction() as connection:
        connection.execute("SELECT pg_advisory_xact_lock(hashtextextended(current_schema() || %s, 0))",
                           (":application-target:" + application,))
        before = _row(connection, binding, lock=" FOR UPDATE")
        revision = int(before["revision"]) if before else 0
        if expected_revision != revision:
            raise ConfigurationConflict("Application configuration revision changed", code="instruction.version_conflict", details={
                "expected_revision": expected_revision, "current_revision": revision,
            })
        value = {**(dict(before) if before else {
            "target_id": "", "admission_paused": False, "reason": "",
        }), **changes}
        target_changed = not before or value["target_id"] != before["target_id"]
        if application == "tau" and before and target_changed and (not before["admission_paused"] or not value["admission_paused"]):
            raise ConfigurationConflict("Pause TAU admission before switching its target; resume separately")
        if target_changed or not value["admission_paused"]:
            if not _available(connection, binding, value["target_id"], lock=True):
                raise KeyError("Application target does not exist or is deleted")
        table, key, key_value, field = binding
        connection.execute(
            f"INSERT INTO {table} ({key},{field},revision,admission_paused,reason,updated_by,updated_at) "
            f"VALUES (%s,%s,%s,%s,%s,%s,%s) ON CONFLICT ({key}) DO UPDATE SET "
            f"{field}=EXCLUDED.{field},revision=EXCLUDED.revision,admission_paused=EXCLUDED.admission_paused,"
            "reason=EXCLUDED.reason,updated_by=EXCLUDED.updated_by,updated_at=EXCLUDED.updated_at",
            (key_value, value["target_id"], revision + 1, value["admission_paused"], value["reason"], actor,
             datetime.now(timezone.utc).isoformat()),
        )
        return _view(connection, application, binding, _row(connection, binding))

@contextmanager
def admission_scope(application: str):
    """Hold the row lock until new work is durable; launch/recovery stay outside."""
    binding = configuration_binding(application)
    if application != "tau":
        raise ConfigurationConflict("This application does not support admission controls")
    with portal_database(schema="lineage").transaction() as connection:
        row = _row(connection, binding, lock=" FOR SHARE")
        if row and row["admission_paused"]:
            raise AdmissionPaused("Application admission is paused", details={
                "application": application, "revision": row["revision"], "reason": row["reason"], "target_id": row["target_id"],
            })
        if not row or not _available(connection, binding, row["target_id"]):
            raise ConfigurationConflict("Application target is not configured or unavailable")
        yield
